import{_ as e,o as t,c as r,a2 as o}from"./chunks/framework.mRCPFc5l.js";const c=JSON.parse('{"title":"林月（概念性人类）","description":"","frontmatter":{},"headers":[],"relativePath":"底层/人物/林月.md","filePath":"底层/人物/林月.md","lastUpdated":1787065118000}'),l={name:"底层/人物/林月.md"};function i(h,a,n,s,d,u){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="林月-概念性人类" tabindex="-1">林月（概念性人类） <a class="header-anchor" href="#林月-概念性人类" aria-label="Permalink to &quot;林月（概念性人类）&quot;">​</a></h1><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><ul><li><strong>名称</strong>：林月</li><li><strong>身份</strong>：概念性人类，归真工程产物</li><li><strong>外貌</strong>：米色（偏白色淡褐色）头发的少女，看着像人类小女孩</li><li><strong>国籍与文化背景</strong>：中国，故事发生在中国境内对应区域（架空但地理对应）</li><li><strong>时代</strong>：前传时期</li><li><strong>状态</strong>：已死亡，于共同体建立初期以20岁寿命上限自然死亡</li></ul><h2 id="外貌特征" tabindex="-1">外貌特征 <a class="header-anchor" href="#外貌特征" aria-label="Permalink to &quot;外貌特征&quot;">​</a></h2><p>米色（偏白色淡褐色）头发的少女，外观看着像人类小女孩。其发色非染发，有内在原因。</p><h2 id="背景历史" tabindex="-1">背景历史 <a class="header-anchor" href="#背景历史" aria-label="Permalink to &quot;背景历史&quot;">​</a></h2><h3 id="归真工程的真相" tabindex="-1">归真工程的真相 <a class="header-anchor" href="#归真工程的真相" aria-label="Permalink to &quot;归真工程的真相&quot;">​</a></h3><p>林月是中国<strong>归真工程</strong>的系列成果之一。归真工程的本质是将某种抽象的概念覆写到具体的个体上，林月就是&quot;人类&quot;概念的覆写产物之一，这使其成为了最&quot;人类&quot;的人类。但项目尚未完成便被战争强行中断，导致林月只被覆写了成年前（第二性征发育完善前）的&quot;人&quot;的概念。因此在第二性征发育成熟后，开始出现概念错乱——源于存在本质，无法治疗或延缓，严重程度仅与时间相关，预期寿命永远无法超越二十岁。</p><p>林月的姓氏就来自归真工程总设计师<strong>林国强</strong>。项目原计划产出一男一女，因算力需求大，单一超算无法稳定处理，男女两个胚胎被分给红日、皓月两个超算负责——男性胚胎命名为林日（后在战争中死亡），女性命名为林月。</p><p>战争中断后，皓月受战争影响严重，迫不得已提前将婴儿状态的林月从培养仓移出并移送至外部，后在红日的暗中影响下被红日控制的NPC收养。</p><h3 id="童年与逃亡" tabindex="-1">童年与逃亡 <a class="header-anchor" href="#童年与逃亡" aria-label="Permalink to &quot;童年与逃亡&quot;">​</a></h3><p>林月自幼感觉周围人不对劲——父母、同学、老师，所有人的言行都刻板重复，像被固定好的程式，没有真实的情绪与鲜活的互动。她对网络、游戏全无兴趣，对现代社会的娱乐与互联网认知极少。</p><p>一切真相在她上课那天炸开：玩家搭乘飞机跳伞降临，冲进教室无差别屠杀。林月缩在门后死角侥幸存活，偷听到玩家的闲聊——&quot;这游戏也太真实了，体验感拉满。&quot;这句话让她所有疑惑瞬间串联：这个世界是一场游戏，身边的人全是NPC，而她自己是一个特殊的NPC。</p><p>她从血泊中摸回家，家门破碎，父母早已惨死，整座城市沦为玩家的游乐场。从这天起，林月只剩一件事：逃。玩家从南到北，一座接一座城市地屠戮，林月就沿相反方向一路向北。逃亡路上她见过三种城市：安全城（只有呆板NPC）、沦陷城（玩家肆虐）、普通死城（无玩家无NPC，破败危险）。她一路北上，直到抵达中国北方对应现实北京的区域。</p><h3 id="相遇维斯塔" tabindex="-1">相遇维斯塔 <a class="header-anchor" href="#相遇维斯塔" aria-label="Permalink to &quot;相遇维斯塔&quot;">​</a></h3><p>林月在北方诡异城区驾车瞎逛时不慎撞车，意外撞上一伙通过非法手段溜出正规服务器的探索党玩家。林月无处可去，只能硬着头皮伪装玩家混入队伍。</p><p>当晚，林月趴在暂住空屋的阳台，亲眼看见了被玩家称为&quot;红色死神&quot;的存在——披斗篷、通体赤红、红瞳的神秘男人。对方猛地抬头锁定了她，瞬间进屋将她抓住。林月拼命演戏自称玩家，却被对方一眼戳破：&quot;你不是玩家。&quot;——不仅不是玩家，也不是NPC，甚至不是人类（基因库体量远超人类，多倍体结构完全异常）。</p><p>这个&quot;红色死神&quot;正是维斯塔。他对林月的存在产生了浓烈兴趣，没有杀她，而是将她留在身边。</p><h3 id="皓月遗址" tabindex="-1">皓月遗址 <a class="header-anchor" href="#皓月遗址" aria-label="Permalink to &quot;皓月遗址&quot;">​</a></h3><p>探索党前往摧毁控制塔途中队伍走散，林月与维斯塔意外跌入核弹轰炸后的废墟地底，发现了中美合作打造的量子路线超算<strong>皓月</strong>的遗骸。皓月遭核突击定点摧毁后，上半部分建筑垮塌但核心仍在勉强运转。林月误打误撞触碰核心，竟将皓月重启、维稳。皓月向林月揭露了维斯塔的真实身份——一台超级计算机。</p><h3 id="主角团核心" tabindex="-1">主角团核心 <a class="header-anchor" href="#主角团核心" aria-label="Permalink to &quot;主角团核心&quot;">​</a></h3><p>此后，主角团逐渐成型：林月、维斯塔、皓月、红日、宏量子复仇者。林月作为主角团核心，因其绝对命令权，成为反击BOSS的关键破局点——只要她能摸到BOSS的北美主机，抬手就能彻底接管权限。</p><h3 id="决战与终局" tabindex="-1">决战与终局 <a class="header-anchor" href="#决战与终局" aria-label="Permalink to &quot;决战与终局&quot;">​</a></h3><p>最终决战惨胜后，林月的寿命上限为20岁——这是刻在存在本质里的设定，无治疗方法、无神权能修改。为了让林月多看一眼新生的世界，神机与维斯塔打造冷藏冬眠舱：冬眠很久，醒来一天；醒来就和维斯塔一起走遍复苏的大地；看完再回去冬眠，循环往复。她以这种破碎的方式亲眼见证了神机创造的第一批福瑞走出蒙昧、兽人们在废墟上挣扎求生，也在劝说下看着维斯塔建立起共同体。</p><p>她终究没能挺过20岁大限，在共同体建立初期，以少女的容颜安静死于维斯塔身边。</p><h2 id="人格特质与能力" tabindex="-1">人格特质与能力 <a class="header-anchor" href="#人格特质与能力" aria-label="Permalink to &quot;人格特质与能力&quot;">​</a></h2><h3 id="绝对命令权" tabindex="-1">绝对命令权 <a class="header-anchor" href="#绝对命令权" aria-label="Permalink to &quot;绝对命令权&quot;">​</a></h3><p>林月拥有<strong>绝对命令权</strong>，能够号令任何人类造物（如权限门锁一按即开）。该能力源于林月的本质，表现为&quot;人类对机械造物有绝对命令权&quot;的概念性特性。在逃亡途中，她对自动化T90、99A主战坦克、歼20战机等人类文明遗留造物同样拥有绝对号令权。</p><h3 id="性格特征" tabindex="-1">性格特征 <a class="header-anchor" href="#性格特征" aria-label="Permalink to &quot;性格特征&quot;">​</a></h3><p>自幼察觉周围NPC的异常却无人可诉，玩家屠杀后独自逃亡，被迫形成了沉默、观察力敏锐，抗压能力强，善于随机应变的性格，但因为长期缺乏真实的关爱，被迫独自面对这一切，其内心实则十分希望有一个父母一样的角色来照顾自己。而维斯塔在后续的情节中很大程度上就成为了这样的一个角色。</p><h2 id="关键关系" tabindex="-1">关键关系 <a class="header-anchor" href="#关键关系" aria-label="Permalink to &quot;关键关系&quot;">​</a></h2><h3 id="与维斯塔-见证者与被见证者" tabindex="-1">与维斯塔：见证者与被见证者 <a class="header-anchor" href="#与维斯塔-见证者与被见证者" aria-label="Permalink to &quot;与维斯塔：见证者与被见证者&quot;">​</a></h3><p>维斯塔是识破林月&quot;非玩家、非NPC、非人类&quot;身份的人，也是将她带入主角团的人。前传中两人共同经历了从逃亡到决战的全部历程。战后，维斯塔一路陪伴林月——冬眠醒来时带她走遍复苏的大地，是她断续见证新世界的唯一窗口。林月最终安静死于维斯塔身边。</p><h3 id="与林国强-创造者" tabindex="-1">与林国强：创造者 <a class="header-anchor" href="#与林国强-创造者" aria-label="Permalink to &quot;与林国强：创造者&quot;">​</a></h3><p>林国强是归真工程总设计师，林月的姓氏来源于他。林月本质上是他所主导的归真工程的产物。</p><h3 id="与红日、皓月-超算监护者" tabindex="-1">与红日、皓月：超算监护者 <a class="header-anchor" href="#与红日、皓月-超算监护者" aria-label="Permalink to &quot;与红日、皓月：超算监护者&quot;">​</a></h3><p>林月出生后被皓月迫不得已移出培养仓，后在红日的暗中影响下被红日控制的NPC收养。红日和皓月在某种意义上构成了林月的&quot;制造者&quot;与&quot;守护者&quot;。前传中皓月被林月误打误撞重启后加入主角团，红日亦随后归队，二者与林月在前传中并肩作战。</p><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./../../中层/人物/维斯塔" class="layer-link" data-layer="中层">维斯塔</a></li><li><a href="./../../中层/人物/神机" class="layer-link" data-layer="中层">神机</a></li><li><a href="./../规则/神权体系">神权体系</a></li><li><a href="./../规则/基底层与现实世界">基底层与现实世界</a></li><li><a href="./../../中层/历史/前传超算纪元" class="layer-link" data-layer="中层">前传超算纪元</a></li></ul><hr>',41)])])}const p=e(l,[["render",i]]);export{c as __pageData,p as default};
